// markOf is the logo of each connection with one, by its key.
var markOf = map[string]string{"claude-desktop": "claude", "claude-code": "claude-code", "codex": "openai", "cursor": "cursor"}

// toolmark draws a tool's logo, or the icon of that name when it has none.
func toolmark(name string) template.HTML {
	if m, ok := markOf[name]; ok {
		name = m
	}
	if l, ok := logos[name]; ok {
		return template.HTML(`<svg class="icon icon--logo" viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" focusable="false">` + l + `</svg>`)
	}
	return icon(name)
}
